import{_ as l,H as a,f as i,i as t}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"26 | 散户的起义：GME逼空华尔街","description":"","frontmatter":{},"headers":[{"level":2,"title":"第一重武器：轧空（Short Squeeze）","slug":"第一重武器-轧空-short-squeeze","link":"#第一重武器-轧空-short-squeeze","children":[]},{"level":2,"title":"第二重武器：伽马挤压（Gamma Squeeze）","slug":"第二重武器-伽马挤压-gamma-squeeze","link":"#第二重武器-伽马挤压-gamma-squeeze","children":[]},{"level":2,"title":"∂Δ","slug":"∂δ","link":"#∂δ","children":[]},{"level":2,"title":"Γ =","slug":"γ","link":"#γ","children":[]},{"level":2,"title":"∂Price","slug":"∂price","link":"#∂price","children":[]},{"level":2,"title":"情绪因子：当信仰变成流动性锁","slug":"情绪因子-当信仰变成流动性锁","link":"#情绪因子-当信仰变成流动性锁","children":[]},{"level":2,"title":"拔网线：游戏终结","slug":"拔网线-游戏终结","link":"#拔网线-游戏终结","children":[]},{"level":2,"title":"AI 量化的新课题：舆情监控","slug":"ai-量化的新课题-舆情监控","link":"#ai-量化的新课题-舆情监控","children":[]},{"level":2,"title":"AI 量化策略建议","slug":"ai-量化策略建议","link":"#ai-量化策略建议","children":[]},{"level":2,"title":"本讲金句弹幕","slug":"本讲金句弹幕","link":"#本讲金句弹幕","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]}],"relativePath":"人人都用得上的AI量化思维课/26｜散户的起义：GME逼空华尔街.md","filePath":"人人都用得上的AI量化思维课/26｜散户的起义：GME逼空华尔街.md","lastUpdated":1795541548000}'),p={name:"人人都用得上的AI量化思维课/26｜散户的起义：GME逼空华尔街.md"};function r(o,e,n,s,h,u){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="_26-散户的起义-gme逼空华尔街" tabindex="-1">26 | 散户的起义：GME逼空华尔街 <a class="header-anchor" href="#_26-散户的起义-gme逼空华尔街" aria-label="Permalink to &quot;26 | 散户的起义：GME逼空华尔街&quot;">​</a></h1><p>你好，我是陈旸。</p><p>2020 年的游戏驿站（GameStop），在华尔街精英眼里，就是一只死票。这是一家卖实体游戏光盘的连锁店。在数字化下载和电商的冲击下，它看起来就像当年的诺基亚，注定要倒闭。股价最低跌到了 2 美元。华尔街的对冲基金们像秃鹫一样盘旋在它头顶，疯狂做空。其中，Melvin Capital（梅尔文资本）最为激进。</p><p>激进到什么程度？GME 的做空比例一度高达 140%。这时候量化视角的警钟敲响了，注意这个数字：140%。这意味着，市面上只有 100 股股票，但被卖空了 140 股。这在数学上是怎么实现的？</p><p>A 借给 B 卖空，B 卖给 C，C 又借给 D 卖空……同一股股票被借了多次。这就像一个堆满了炸药桶的房间。只要有一点火星，整个房间就会爆炸。华尔街的精英们太傲慢了，他们笃定GME 会归零，所以无视了这个显而易见的流动性风险。直到那个带头大哥——Keith Gill 点燃了火柴。</p><h2 id="第一重武器-轧空-short-squeeze" tabindex="-1">第一重武器：轧空（Short Squeeze） <a class="header-anchor" href="#第一重武器-轧空-short-squeeze" aria-label="Permalink to &quot;第一重武器：轧空（Short Squeeze）&quot;">​</a></h2><p>Keith Gill 不是普通散户，他是专业的金融分析师。他发现 GME 被严重低估了（还有现金流，新主机要发布），且做空比例太高。他在 Reddit 的 WallStreetBets（WSB）板块上晒出了自己的多单，并喊出了口号： YOLO（You Only Live Once，你只活一次，梭哈！）散户们集结起来，开始疯狂买入 GME 股票。股价开始上涨。这时候，第一重数学机制启动了：轧空。</p><p>原理：</p><ol><li><p>Melvin Capital 借了股票卖出（做空），现在股价涨了，他们亏损了。</p></li><li><p>为了止损（或者被追加保证金），他们必须买回股票还给券商。</p></li><li><p>关键点：他们买回股票的动作，会进一步推高股价。</p></li><li><p>股价更高 =&gt; 亏损更多 =&gt; 需要买回更多 =&gt; 股价更高。</p></li></ol><p>这是一个正反馈循环。但这只是常规武器。真正让华尔街崩溃的，是散户们发现的第二重核武器——期权。</p><h2 id="第二重武器-伽马挤压-gamma-squeeze" tabindex="-1">第二重武器：伽马挤压（Gamma Squeeze） <a class="header-anchor" href="#第二重武器-伽马挤压-gamma-squeeze" aria-label="Permalink to &quot;第二重武器：伽马挤压（Gamma Squeeze）&quot;">​</a></h2><p>如果散户只是买股票，资金量是有限的。散户那点钱，怎么撬动几百亿的基金？答案是：杠杆。散户们没有直接买正股，而是疯狂买入看涨期权（Call Options）。期权很便宜，几百美元就能控制价值几万美元的股票。这时候，期权市场的做市商（如 Citadel）被迫卷入了战争。</p><p>请集中注意力，这里是本讲最硬核的量化知识：做市商是卖期权给你的人。他是开赌场的，他不赌方向，他要保持中性。当你从做市商手里买入一份 Call（看涨期权）时，做市商就持有了一份空头头寸。为了对冲风险，做市商必须在股票市场上买入一定数量的正股。</p><p>买多少？</p><p>这由期权的 Delta 值决定。股价低时，期权是虚值的，Delta 很小（比如 0.1），做市商只需买一点点股票。但是，随着股价上涨，期权从虚值变成实值，Delta 会迅速变大（接近 1）。</p><p>Gamma 的概念：</p><p>Gamma 是 Delta 随价格变化的速率（加速度）。</p><h2 id="∂δ" tabindex="-1">∂Δ <a class="header-anchor" href="#∂δ" aria-label="Permalink to &quot;∂Δ&quot;">​</a></h2><h2 id="γ" tabindex="-1">Γ = <a class="header-anchor" href="#γ" aria-label="Permalink to &quot;Γ =&quot;">​</a></h2><h2 id="∂price" tabindex="-1">∂Price <a class="header-anchor" href="#∂price" aria-label="Permalink to &quot;∂Price&quot;">​</a></h2><ul><li>​</li></ul><p>伽马挤压的死亡螺旋：</p><ol><li><p>散户疯狂买入 Call =&gt; 做市商为了对冲，必须买入正股。</p></li><li><p>做市商买入正股 =&gt; 推高股价。</p></li><li><p>股价上涨 =&gt; 触发 Gamma 效应 =&gt; 期权的 Delta 变大。</p></li><li><p>Delta 变大 =&gt; 做市商必须再买入更多的正股来对冲。</p></li><li><p>做市商买入更多 =&gt; 股价继续暴涨……</p></li></ol><p>看懂了吗？做市商变成了散户的免费打手。散户每买一张期权，就强迫做市商像机器一样去买正股。股价越高，做市商买得越猛。这就是为什么 GME 的股价能从 20 美元一路飙升到 483美元。这在物理学上叫共振。散户找到了系统的固有频率，把这座大桥震塌了。</p><h2 id="情绪因子-当信仰变成流动性锁" tabindex="-1">情绪因子：当信仰变成流动性锁 <a class="header-anchor" href="#情绪因子-当信仰变成流动性锁" aria-label="Permalink to &quot;情绪因子：当信仰变成流动性锁&quot;">​</a></h2><p>在传统的量化模型中，我们假设投资者是理性的：赚了钱就会止盈。所以，Melvin Capital 一开始以为：“涨这么多了，散户肯定会卖的，我只要扛一扛就过去了。”但他错了。他遇到了一群不理性的疯子。在 WSB 论坛上，流行着一种文化：钻石手。意思就是：哪怕亏光，我也绝对不卖。他们互相晒单，谁卖谁就是叛徒，谁持有谁就是英雄。</p><p>量化视角的解读这导致了流动性枯竭。</p><ul><li><p>买盘：源源不断的期权做市商回补 + 空头止损。</p></li><li><p>卖盘：几乎为零（因为散户锁仓了）。</p></li></ul><p>当供需曲线垂直时，价格是由买方说了算的。Melvin Capital 想买回股票平仓？对不起，没人卖给你。你出多少钱都不卖。最终，Melvin Capital 巨亏 53%，不得不寻求注资救命。这也宣告了传统基本面量化策略的失效。在 GME 事件中，你看 PE、PB、现金流，全是错的。唯一的因子就是情绪。</p><h2 id="拔网线-游戏终结" tabindex="-1">拔网线：游戏终结 <a class="header-anchor" href="#拔网线-游戏终结" aria-label="Permalink to &quot;拔网线：游戏终结&quot;">​</a></h2><p>这场狂欢是如何结束的？不是因为空头赢了，而是因为赌场关门了。2021 年 1 月 28 日，散户常用的交易软件 Robinhood 突然宣布：禁止买入 GME，只能卖出。理由是：由于波动剧烈，清算所（DTCC）要求 Robinhood 缴纳巨额保证金，Robinhood 没钱了。这一招拔网线，直接切断了买盘。</p><ul><li><p>只能卖，不能买 =&gt; 供需瞬间逆转。</p></li><li><p>恐慌蔓延，Gamma Squeeze 反向运行。</p></li><li><p>股价从 483 美元自由落体。</p></li></ul><p>虽然散户最后输了钱，但他们证明了一件事：只要足够团结，利用金融工程的规则，蚂蚁真的可以咬死大象。</p><h2 id="ai-量化的新课题-舆情监控" tabindex="-1">AI 量化的新课题：舆情监控 <a class="header-anchor" href="#ai-量化的新课题-舆情监控" aria-label="Permalink to &quot;AI 量化的新课题：舆情监控&quot;">​</a></h2><p>GME 事件后，华尔街发生了一场革命。所有的量化基金都意识到：必须监控社交媒体。如果你的 AI 模型里还没有加入社交媒体因子，你就已经被时代淘汰了。</p><p>现在的 AI 是如何捕捉下一个 GME 的？</p><ol><li>另类数据源</li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%BA%E4%BA%BA%E9%83%BD%E7%94%A8%E5%BE%97%E4%B8%8A%E7%9A%84AI%E9%87%8F%E5%8C%96%E6%80%9D%E7%BB%B4%E8%AF%BE/images/26/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%BA%E4%BA%BA%E9%83%BD%E7%94%A8%E5%BE%97%E4%B8%8A%E7%9A%84AI%E9%87%8F%E5%8C%96%E6%80%9D%E7%BB%B4%E8%AF%BE/images/26/1.png" alt=""></a></p><ol start="2"><li>核心指标计算</li></ol><ul><li><p>提及量：GME 今天被提到了多少次？如果比昨天暴增 1000%，预警。</p></li><li><p>情绪极性：大家是在骂它还是在夸它？</p></li><li><p>表情包分析：AI 学会了识别 （火箭）和 💎🙌（钻石手）。如果一个帖子里全是，AI 判定为：极度狂热 / 逼空前兆。</p></li></ul><ol start="3"><li>结合期权异动</li></ol><p>AI 不仅看舆情，还看期权链。如果某只股票的舆情热度飙升，同时看涨 / 看跌比异常升高，且隐含波动率（IV）暴涨。AI 会立刻发出信号：伽马挤压（Gamma Squeeze）可能正在形成，启动跟随策略。”</p><h2 id="ai-量化策略建议" tabindex="-1">AI 量化策略建议 <a class="header-anchor" href="#ai-量化策略建议" aria-label="Permalink to &quot;AI 量化策略建议&quot;">​</a></h2><p>GME 事件是金融史上的一座丰碑。它留给我们的教训是深刻的。</p><ol><li>永远不要做空模因股（Meme Stocks，因社区情绪而暴涨的股票）”</li></ol><p>量化交易有一个铁律：不要做空波动率无限的资产。一只垃圾股，价格可以涨到天上去。做多的最大亏损是 100%（归零），做空的最大亏损是无穷大。当 AI 提示某只股票具有“Meme 属性”时，哪怕它基本面再烂，也禁止做空。</p><ol start="2"><li>关注结构性拥挤</li></ol><p>在选股时，看一眼做空比例。如果一只股票的做空比例超过 30%，说明空头太拥挤了。这时候，只要有一点利好，就容易引发踩踏式上涨。这反而是做多的好机会（博弈空头回补）。</p><ol start="3"><li>情绪是短期最强的因子</li></ol><p>在 A 股，这就是连板战法。当市场情绪被点燃时，估值是没有意义的。作为量化交易者，我们要学会与泡沫共舞，利用 AI 监控情绪的热度。当满屏都是火箭时，跟随买入；当 AI 检测到火箭数量开始下降时，果断离场，不要做最后的钻石手。</p><h2 id="本讲金句弹幕" tabindex="-1">本讲金句弹幕 <a class="header-anchor" href="#本讲金句弹幕" aria-label="Permalink to &quot;本讲金句弹幕&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%BA%E4%BA%BA%E9%83%BD%E7%94%A8%E5%BE%97%E4%B8%8A%E7%9A%84AI%E9%87%8F%E5%8C%96%E6%80%9D%E7%BB%B4%E8%AF%BE/images/26/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%BA%E4%BA%BA%E9%83%BD%E7%94%A8%E5%BE%97%E4%B8%8A%E7%9A%84AI%E9%87%8F%E5%8C%96%E6%80%9D%E7%BB%B4%E8%AF%BE/images/26/2.png" alt=""></a></p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>这一讲，我们讲了散户利用伽马挤压（Gamma Squeeze）和情绪因子击败机构的故事。这告诉我们：</p><ol><li><p>市场结构（期权对冲机制）比基本面更重要。</p></li><li><p>情绪是可以被量化、被利用的。</p></li><li><p>资金优势不是绝对的，规则优势才是。</p></li></ol><p>到这里，我们的第四章“风控与反脆弱”中关于外部风险（黑天鹅、闪崩、逼空）的部分就讲完了。但是，除了外部的敌人，量化交易还有一个内部的敌人。这个敌人藏在你的模型里，藏在你的回测报告里。它会用完美的曲线欺骗你，让你以为找到了圣杯，最后在实盘中让你亏得底裤都不剩。这就是过拟合与幸存者偏差。下一讲，我们将揭开量化回测中最大的骗局。</p>',56)])])}const d=l(p,[["render",r]]);export{c as __pageData,d as default};
